INSERT INTO policies (slug, title, body, sort) VALUES ('payment', 'Payment', 'Full payment is required at checkout. Pay by card, bank transfer or USSD through Paystack. Your booking is confirmed automatically once Paystack verifies the payment.', 0);
INSERT INTO policies (slug, title, body, sort) VALUES ('cancellations', 'Cancellations', 'Cancel 72 hours or more before your session for a full refund. Between 24 and 72 hours, 50% is refunded. Under 24 hours or no-shows are not refunded.', 1);
INSERT INTO policies (slug, title, body, sort) VALUES ('rescheduling', 'Rescheduling', 'Reschedule once for free, up to 48 hours before your session, to any open slot. Later changes are treated as a cancellation.', 2);
INSERT INTO policies (slug, title, body, sort) VALUES ('late-arrivals', 'Late arrivals', 'Sessions start and end at the booked time. Time lost to late arrival is not added on, so the next client is not delayed.', 3);
INSERT INTO policies (slug, title, body, sort) VALUES ('overtime', 'Overtime', 'Overtime is ₦20,000 per hour, billed in 30 minute blocks, and only when the studio is free after your session.', 4);
INSERT INTO policies (slug, title, body, sort) VALUES ('refunds', 'Refunds', 'Approved refunds go back to the original payment method within 5 to 10 working days.', 5);
INSERT INTO policies (slug, title, body, sort) VALUES ('guests-conduct', 'Guests and conduct', 'Up to 6 people per session, including the artist. No smoking, drugs or weapons. Unsafe behaviour ends a session without a refund.', 6);
INSERT INTO policies (slug, title, body, sort) VALUES ('files', 'File delivery and storage', 'Files are shared by download link within 48 hours. Project files are kept for 30 days after your session, then deleted.', 7);
INSERT INTO content (key, value) VALUES ('hero_title', 'Your sound, recorded right.');
INSERT INTO content (key, value) VALUES ('hero_subtitle', 'Book real studio time in Lekki, Lagos. See live availability, pay with Paystack, walk in and record.');
